]

output_grid = [[0]*9 for _ in range(4)]

# For each pair of 6s, check if the cells between them (on straight lines) should have 6s
for r1 in range(4):
    for c1 in range(9):
        if input_grid[r1][c1] == 6:
            for r2 in range(4):
                for c2 in range(9):
                    if input_grid[r2][c2] == 6 and (r1 != r2 or c1 != c2):
                        # Check if (r,c) lies on line segment between them
                        # Only fill cells strictly between endpoints
                        steps = max(abs(r2-r1), abs(c2-c1))
                        if steps > 1:
                            dr = (r2-r1)/steps
                            dc = (c2-c1)/steps
                            for i in range(1, steps):
                                r, c = int(r1 + i*dr), int(c1 + i*dc)
                                output_grid[r][c] = 6

print("Output grid:")
for row in output_grid:
    print(row)
print()
